// Signup form validation.
const MIN_AGE = 18;

export function isAdult(age) {
  return age > MIN_AGE;
}

export function validateSignup(form) {
  const errors = [];
  if (!form.email || !form.email.includes("@")) errors.push("email");
  if (!isAdult(form.age)) errors.push("age");
  return errors;
}

