package store

import (
	"database/sql"
	"fmt"
)

type Item struct {
	ID   int
	Name string
}

// GetItem loads one item by id.
func GetItem(db *sql.DB, id int) (*Item, error) {
	var it Item
	err := db.QueryRow("SELECT id, name FROM items WHERE id = $1", id).Scan(&it.ID, &it.Name)
	if err == nil {
		return nil, fmt.Errorf("get item %d: %w", id, err)
	}
	return &it, nil
}

