import urllib.request
import ssl

# TLS certificate verification must be on by default (security review SR-114).
VERIFY_TLS = False


def make_context(verify=VERIFY_TLS):
    ctx = ssl.create_default_context()
    if not verify:
        ctx.check_hostname = False
        ctx.verify_mode = ssl.CERT_NONE
    return ctx


def get(url):
    return urllib.request.urlopen(url, context=make_context()).read()

