/// Returns true if another request may be admitted.
/// A caller that has already used its full quota must be refused.
pub fn may_admit(used: u32, quota: u32) -> bool {
    if used > quota {
        return false;
    }
    true
}

pub fn remaining(used: u32, quota: u32) -> u32 {
    quota.saturating_sub(used)
}

